// Reuses pinned Read33 typed mapping; adds only installed cond for one preserved Boolean if.
import fs from 'node:fs';import crypto from 'node:crypto';import zlib from 'node:zlib';import assert from 'node:assert/strict';
const repo='/Users/casey.allard/lexlean-r4-worktrees/model-port';
const base='/Users/casey.allard/lexlean-r4-evidence/2026-10-24/object-read-native-controls';
const root='/Users/casey.allard/lexlean-r4-evidence/2026-10-24/object-read-composed-dependencies';
const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const sorted=x=>Array.isArray(x)?x.map(sorted):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,sorted(x[k])])):x;
const compact=x=>JSON.stringify(sorted(x));
const deps=new Map();const pin=p=>{const b=fs.readFileSync(p);const r={path:p,bytes:b.length,sha256:hash(b)};deps.set(p,r);return r};
const load=p=>{pin(p);return JSON.parse(fs.readFileSync(p,'utf8'))};
const parse=p=>{pin(p);return JSON.parse(fs.readFileSync(p,'utf8').match(/^\\semanticdata\{(.*)\}$/m)[1]);};
const core=p=>{pin(p);return JSON.parse(fs.readFileSync(p,'utf8').match(/^\\coredata\{(.*)\}$/m)[1]);};
const allocated=()=>{let total=0;function w(p){for(const e of fs.readdirSync(p,{withFileTypes:true})){const q=p+'/'+e.name;const s=fs.lstatSync(q);total+=s.blocks*512;if(e.isDirectory())w(q)}}w(root);return total};
const budget=[];function gate(label,extra=0){const s=fs.statfsSync(root,{bigint:true});const free=s.bavail*s.bsize;assert(free>=10n*1024n**3n+1048576n);assert(allocated()+extra<=1048576);budget.push({label,freeBytes:String(free),allocatedBytes:allocated(),reservedAdditionalBytes:extra});}
function put(name,b){b=Buffer.isBuffer(b)?b:Buffer.from(typeof b==='string'?b:JSON.stringify(b,null,2)+'\n');gate(name,Math.ceil(b.length/4096)*4096+8192);const p=root+'/'+name;fs.mkdirSync(p.slice(0,p.lastIndexOf('/')),{recursive:true});fs.writeFileSync(p,b,{flag:'wx'});return {path:name,bytes:b.length,sha256:hash(b)}}
const proposal=pin(base+'/ordinal26-semantic-boundary-successor-proposal.json');assert.equal(proposal.sha256,'323165e4abadb9817351906876cb3ae96275da70139cc0f35d9b52241e4f1f36');
const spec=pin(base+'/ordinal26-semantic-boundary-successor-spec-review.json');assert.equal(spec.sha256,'65f69e3fa932cca644b46cd3399435265a72ff7da92713a3980be33b13925a2c');
const oldBindings=load(base+'/source-bindings.json');const oldInputs=load(base+'/invocation/ordinal26-negative/expected-inputs.json');
assert.equal(oldInputs.length,33);const source=destination=>{const r=oldInputs.find(x=>x.destination===destination);assert(r,destination);const p=pin(r.source);assert.equal(p.sha256,r.sha256);assert.equal(p.bytes,r.bytes);return r.source};
for(const r of oldInputs){const p=pin(r.source);assert.equal(p.sha256,r.sha256);assert.equal(p.bytes,r.bytes);}
const frozenRead=pin(base+'/manifest.json');assert.equal(frozenRead.sha256,'539ad628ae2987965285ce596e918bb1470288990804ab2246bc7944c4fdb21f');
const priorAuthor=pin(base+'/author-read33.mjs');const prelude=pin(base+'/installed-lean-source/Prelude.lean.stdout');assert(fs.readFileSync(prelude.path,'utf8').includes('def cond {α : Sort u} (c : Bool) (x y : α) : α'));
const pendingPath=repo+'/docs/continuation/2026-10-23/pending-manifest.json',pending=load(pendingPath);assert.equal(pending.files.length,17);const preservation=pending.files.map(r=>{const current=pin(repo+'/'+r.originalPath),snapshot=pin(repo+'/docs/continuation/2026-10-23/'+r.snapshotPath);assert.equal(snapshot.sha256,r.sha256);assert.equal(snapshot.bytes,r.bytes);return {originalPath:r.originalPath,current,snapshot}});
const runtime=new Map();const runtimePins=[];for(const name of ['ObjectTypes','ObjectCodec','ObjectStore','ObjectRead','Object']){const p=source('src/R4/'+name+'.lex.tex');runtimePins.push(pin(p));for(const d of parse(p).declarations)runtime.set('LexLeanR4.R4.'+name+'.'+d.name,{...d,owner:'R4.'+name});}
const q=(m,owner)=>'LexLeanR4.'+(m.module||owner)+'.'+m.name;
function type(t,owner){switch(t.kind){case'nat':return 'Nat';case'bool':return 'Bool';case'list':return ['List',type(t.element,owner)];case'result':return ['Except',type(t.error,owner),type(t.ok,owner)];case'named':assert.equal(t.arguments.length,0);return q(t.member,owner);default:throw Error('type '+compact(t));}}
const nodes=[],ids=new Map();const n=x=>{const k=compact(x);if(ids.has(k))return ids.get(k);const i=nodes.length;nodes.push(sorted(x));ids.set(k,i);return i};
const Z={k:'z'},ONE={k:'s',a:Z};const C=(name,u=[])=>n({k:'c',n:name,u});const app=(f,...xs)=>xs.reduce((f,x)=>n({k:'a',f,x}),f);const lam=(name,t,v)=>n({k:'l',n:name,b:'e',t,v});const bv=i=>n({k:'b',i});
function ty(t){if(typeof t==='string')return C(t);if(t[0]==='List')return app(C('List',[Z]),ty(t[1]));if(t[0]==='Except')return app(C('Except',[Z,Z]),ty(t[1]),ty(t[2]));throw Error('kernel type');}
function signature(name){const d=runtime.get(name);assert(d,'signature '+name);return d;}
function equalType(a,b){assert.deepEqual(a,b);}
const mappings=[];
// View is a source-derived, explicitly typed expression tree, separate from kernel node numbering.
function tr(e,env=[],path=''){let id,t,view;const sub=(x,s)=>tr(x,env,path+s);switch(e.kind){
case'nat':id=n({k:'n',v:e.value});t='Nat';view=['nat',e.value];break;
case'bool':id=C(e.value?'Bool.true':'Bool.false');t='Bool';view=['bool',e.value];break;
case'var':{const index=env.findIndex(x=>x.name===e.name);assert(index>=0);t=env[index].type;id=bv(index);view=['var',index,t];break;}
case'nil':t=['List',type(e.element,'ObjectReadControls')];id=app(C('List.nil',[Z]),ty(t[1]));view=['nil',t[1]];break;
case'cons':{const h=sub(e.head,'.head'),tl=sub(e.tail,'.tail');assert.equal(tl.type[0],'List');equalType(h.type,tl.type[1]);t=tl.type;id=app(C('List.cons',[Z]),ty(t[1]),h.id,tl.id);view=['cons',t[1],h.view,tl.view];break;}
case'record':{t=q(e.type,'ObjectReadControls');const d=signature(t);assert.equal(d.kind,'structure');assert.equal(e.fields.length,d.fields.length);const vs=d.fields.map(f=>{const raw=e.fields.find(x=>x.field===f.name);assert(raw);const v=sub(raw.value,'.fields.'+e.fields.indexOf(raw)+'.value');equalType(v.type,type(f.type,d.owner));return v;});id=app(C(t+'.mk'),...vs.map(v=>v.id));view=['record',t,d.fields.map((f,i)=>[f.name,vs[i].view])];break;}
case'constructor':{const name=e.constructor.name;const vs=e.arguments.map((x,i)=>sub(x,'.arguments.'+i));if(name.startsWith('Result.')){assert.equal(e.type_arguments.length,2);t=['Except',type(e.type_arguments[1],'ObjectReadControls'),type(e.type_arguments[0],'ObjectReadControls')];const which=name==='Result.error'?'error':'ok';equalType(vs[0].type,t[which==='error'?1:2]);assert.equal(vs.length,1);id=app(C('Except.'+which,[Z,Z]),ty(t[1]),ty(t[2]),vs[0].id);view=['constructor','Except.'+which,t,vs.map(v=>v.view)];}else{const full=q(e.constructor,'ObjectReadControls'),cut=full.lastIndexOf('.');t=full.slice(0,cut);const d=signature(t),ctor=d.constructors.find(x=>x.name===full.slice(cut+1));assert(ctor);assert.equal(vs.length,ctor.fields.length);vs.forEach((v,i)=>equalType(v.type,type(ctor.fields[i],d.owner)));id=app(C(full),...vs.map(v=>v.id));view=['constructor',full,t,vs.map(v=>v.view)];}break;}
case'call':{const name=q(e.function,'ObjectReadControls'),d=signature(name),vs=e.arguments.map((x,i)=>sub(x,'.arguments.'+i));assert.equal(vs.length,d.parameters.length);vs.forEach((v,i)=>equalType(v.type,type(d.parameters[i].type,d.owner)));t=type(d.result,d.owner);id=app(C(name),...vs.map(v=>v.id));view=['call',name,t,vs.map(v=>v.view)];break;}
case'project':{const v=sub(e.value,'.value'),d=signature(v.type),i=d.fields.findIndex(f=>f.name===e.field);assert(i>=0);t=type(d.fields[i].type,d.owner);id=n({k:'j',n:v.type+'.'+e.field,s:v.type,i,x:v.id});view=['project',v.type,e.field,i,v.view];break;}
case'match':{const v=sub(e.scrutinee,'.scrutinee');assert.equal(v.type[0],'Except');assert.equal(e.branches.length,2);const branches=['error','ok'].map((k,i)=>{const branch=e.branches.find(b=>b.constructor.name==='Result.'+k);assert(branch);assert.equal(branch.binders.length,1);const bt=v.type[i+1];const body=tr(branch.body,[{name:branch.binders[0],type:bt},...env],path+'.branches.'+e.branches.indexOf(branch)+'.body');return {body,bt,id:lam(branch.binders[0],ty(bt),body.id)};});equalType(branches[0].body.type,branches[1].body.type);t=branches[0].body.type;const motive=lam('_result',ty(v.type),ty(t));id=app(C('Except.casesOn',[ONE,Z,Z]),ty(v.type[1]),ty(v.type[2]),motive,v.id,...branches.map(b=>b.id));view=['match',v.type,t,v.view,...branches.map(b=>b.body.view)];break;}
default:throw Error('expression '+e.kind+' at '+path);}
mappings.push({path,node:id,type:t,viewSha256:hash(compact(view))});return {id,type:t,view};}
// Independent structural decoding of the constructed kernel DAG; no evaluation of production functions.
function spine(i){const xs=[];while(nodes[i].k==='a'){xs.unshift(nodes[i].x);i=nodes[i].f}return {head:nodes[i],headId:i,args:xs};}
function decodeType(i){const {head,args}=spine(i);assert.equal(head.k,'c');if(head.n==='List'){assert.deepEqual(head.u,[Z]);assert.equal(args.length,1);return ['List',decodeType(args[0])];}if(head.n==='Except'){assert.deepEqual(head.u,[Z,Z]);assert.equal(args.length,2);return ['Except',...args.map(decodeType)];}assert.equal(args.length,0);assert.deepEqual(head.u,[]);return head.n;}
function decode(i,t,env=[]){const a=nodes[i];if(a.k==='n'){assert.equal(t,'Nat');return ['nat',a.v];}if(a.k==='b'){equalType(t,env[a.i]);return ['var',a.i,t];}if(a.k==='j'){const d=signature(a.s);assert.equal(a.n,a.s+'.'+d.fields[a.i].name);equalType(t,type(d.fields[a.i].type,d.owner));return ['project',a.s,d.fields[a.i].name,a.i,decode(a.x,a.s,env)];}
const {head,args}=spine(i);assert.equal(head.k,'c');const name=head.n;if(name==='Bool.true'||name==='Bool.false'){assert.equal(t,'Bool');return ['bool',name==='Bool.true'];}if(name==='List.nil'){equalType(t,['List',decodeType(args[0])]);assert.equal(args.length,1);return ['nil',t[1]];}if(name==='List.cons'){assert.equal(args.length,3);equalType(t,['List',decodeType(args[0])]);return ['cons',t[1],decode(args[1],t[1],env),decode(args[2],t,env)];}
if(name==='Except.error'||name==='Except.ok'){assert.equal(args.length,3);equalType(t,['Except',decodeType(args[0]),decodeType(args[1])]);return ['constructor',name,t,[decode(args[2],t[name.endsWith('error')?1:2],env)]];}
if(name==='Except.casesOn'){assert.deepEqual(head.u,[ONE,Z,Z]);assert.equal(args.length,6);const scrut=['Except',decodeType(args[0]),decodeType(args[1])];const motive=nodes[args[2]];assert.equal(motive.k,'l');equalType(decodeType(motive.t),scrut);equalType(decodeType(motive.v),t);const bs=[4,5].map((j,k)=>{const b=nodes[args[j]];assert.equal(b.k,'l');equalType(decodeType(b.t),scrut[k+1]);return decode(b.v,t,[scrut[k+1],...env]);});return ['match',scrut,t,decode(args[3],scrut,env),...bs];}
if(name.endsWith('.mk')){const d=signature(name.slice(0,-3));assert.equal(d.kind,'structure');assert.equal(args.length,d.fields.length);assert.equal(t,name.slice(0,-3));return ['record',t,d.fields.map((f,j)=>[f.name,decode(args[j],type(f.type,d.owner),env)])];}
if(runtime.has(name)){const d=signature(name);equalType(t,type(d.result,d.owner));assert.equal(args.length,d.parameters.length);return ['call',name,t,args.map((x,j)=>decode(x,type(d.parameters[j].type,d.owner),env))];}
const cut=name.lastIndexOf('.'),d=signature(name.slice(0,cut)),co=d.constructors.find(x=>x.name===name.slice(cut+1));assert(co);assert.equal(t,name.slice(0,cut));assert.equal(args.length,co.fields.length);return ['constructor',name,t,args.map((x,j)=>decode(x,type(co.fields[j],d.owner),env))];}

const inner=parse(source('tests/lexlean/ObjectWholeInnerContinuation.lex.tex')).declarations[0];let outcome;try{tr(inner.statement.right,[],'inner.statement.right');throw Error('Unexpected predecessor translator success')}catch(e){assert.match(e.message,/expression if at/);outcome={status:'SOURCE_COMPATIBILITY_RED_OBSERVED',error:e.message,scope:'Original pinned Read33 translator rejects existing semantic if; not SDK or native proof negative',native:'NOT_RUN',priorAuthor};}console.log(JSON.stringify(outcome,null,2));
